import * as E from './engine.js';
function col(key,label,opts={}){return {key,label,value:r=>r[key],...opts};}
const price=(key,label)=>col(key,label,{numeric:true,roundCopy:true,exportLabel:label+'(만원/평)',width:108});
const money=(key,label)=>col(key,label,{numeric:true,exportLabel:label+'(만 원)',width:108});
const base=[col('name','단지명',{width:140}),col('year','건축년도',{sort:r=>Number(r.year.split(',')[0])||Infinity}),col('dong','행정동',{exportLabel:'행정동(원본 동)'}),col('region','시군구'),col('address','주소',{width:80})];
const groupPeriod=[col('period','기간',{width:130}),col('group','집계 대상',{width:180})];
export const COLUMNS={periods:[...groupPeriod,col('typeText','타입',{width:76,sort:r=>r.type}),money('priceMinimum','최소 거래금액'),money('priceMaximum','최대 거래금액'),money('priceAverage','평균 거래금액'),price('minimum','최소평당가'),price('maximum','최대평당가'),price('average','평균평당가'),col('count','거래 건수',{numeric:true,value:r=>r.count||null})],volume:[...groupPeriod,col('count','거래 건수',{numeric:true,width:130})],apartments:[...base,col('pyeongText','면적(평형)',{sort:r=>r.areaMin,tie:r=>r.areaMax,width:110}),col('areaText','전용면적(㎡)',{sort:r=>r.areaMin,tie:r=>r.areaMax,width:120}),col('typeText','타입',{width:76,sort:r=>r.type}),price('minimum','최소평당가'),price('maximum','최대평당가'),price('average','평균평당가'),money('priceMinimum','최소 거래금액'),money('priceMaximum','최대 거래금액'),money('priceAverage','평균 거래금액'),col('count','거래 건수',{numeric:true})],districts:[base[2],base[3],base[0],base[1],price('average','평균평당가'),col('count','거래 건수',{numeric:true})],excluded:[col('rowNumber','원본 행',{numeric:true}),base[0],base[4],col('area','전용면적(㎡)',{value:r=>Number.isFinite(r.area)?E.areaText(r.area):'',sort:r=>r.area}),col('broker','중개사 소재지',{width:230}),col('reason','제외 사유',{width:160})],cases:[col('date','계약일',{value:r=>r.date||'날짜 미확인',sort:r=>r.date||'9999'}),base[0],col('pyeongText','평형',{value:r=>E.range(r.area/E.SQM_PER_PYEONG,r.area/E.SQM_PER_PYEONG,'평',2),sort:r=>r.area,width:90}),col('area','전용면적(㎡)',{value:r=>E.areaText(r.area),sort:r=>r.area}),col('type','타입',{value:r=>r.type+'타입',sort:r=>r.type}),col('floor','층',{sort:r=>E.number(r.floor)}),money('price','거래금액'),price('unitPrice','평당가')]};

export function rentalColumns(lease='전세'){
 const count=col('count','거래 건수',{numeric:true,width:110});
 const skipped=col('adjustedMissingCount','환산 제외',{numeric:true,width:105,value:r=>r.adjustedMissingCount||0});
 const jeonse=[money('priceMinimum','최소 전세금'),money('priceMaximum','최대 전세금'),money('priceAverage','평균 전세금'),price('minimum','최소 전세 평당가'),price('maximum','최대 전세 평당가'),price('average','평균 전세 평당가')].map(c=>({...c,width:c.key.startsWith('price')?118:140}));
 const averages=[money('depositAverage','평균 실제 보증금'),money('rentAverage','평균 실제 월세')].map(c=>({...c,width:140,decimals:2,exportLabel:c.key==='rentAverage'?'평균 실제 월세(만 원/월)':c.exportLabel}));
 const adjusted=[money('adjustedMinimum','최소 환산 월세'),money('adjustedMaximum','최대 환산 월세'),money('adjustedAverage','평균 환산 월세')].map(c=>({...c,width:140,decimals:2,exportLabel:c.label+'(만 원/월)'}));
 const amounts=lease==='전세'?[...jeonse,count]:[...averages,...adjusted,count,skipped];
 const periodAmounts=lease==='전세'?jeonse:[...averages,...adjusted.map((c,i)=>({...c,key:['priceMinimum','priceMaximum','priceAverage'][i],value:r=>r[['priceMinimum','priceMaximum','priceAverage'][i]]}))];
 const details=[col('lease','전세·월세'),col('contract','신규·갱신'),money('deposit','실제 보증금'),{...money('rent','실제 월세'),exportLabel:'실제 월세(만 원/월)'},col('rate','적용 전환율',{value:r=>r.rate==null?null:Number(r.rate.toFixed(4))+'%',sort:r=>r.rate??Infinity,width:110}),col('rateRegion','적용 지역',{width:130}),col('targetDeposit','기준 보증금',{numeric:true,width:120,exportLabel:'기준 보증금(만 원)'}),{...money('adjustedRent','환산 월세'),exportLabel:'환산 월세(만 원/월)',decimals:2,width:120},col('adjustedStatus','환산 상태',{width:190})];
 return {periods:[...groupPeriod,col('typeText','타입',{width:76,sort:r=>r.type}),...periodAmounts,{...count,value:r=>r.count||null},...(lease==='월세'?[skipped]:[])],apartments:[...COLUMNS.apartments.slice(0,8),...amounts],districts:[base[2],base[3],base[0],base[1],...amounts],excluded:[...COLUMNS.excluded.slice(0,4),col('lease','전세·월세'),col('contract','신규·갱신'),money('deposit','보증금'),money('rent','월세'),col('reason','제외 사유',{width:160})],cases:[...COLUMNS.cases.slice(0,6),...(lease==='전세'?[details[0],details[1],money('deposit','전세금'),price('unitPrice','전세 평당가')]:details)]};
}
